<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getTrials, getTrialOptions, getTrial, saveTrial, startTrial, reviewTrial, exportTrial, type Trial, type TrialOptions } from '@/api/modules/pilotDelivery'
const loading = ref(false), error = ref(''), rows = ref<Trial[]>([]), selected = ref<Trial | null>(null), editOpen = ref(false), startOpen = ref(false), detailOpen = ref(false), reviewOpen = ref(false)
const options = ref<TrialOptions>({ platforms: [], projects: [], message: '' })
const form = reactive({ name: '', platformIds: [] as number[], newPlatformId: null as number | null, projectIds: [] as number[], baseline: { moldLeadDays: null as number | null, bomPushMinutes: null as number | null, fileLookupMinutes: null as number | null, communicationMinutes: null as number | null }, reason: '' })
const start = reactive({ startedOn: '', mexicoAccessVerified: false, supplierVerified: false, erpVerified: false })
const review = reactive({reviewOn:'',outcome:'passed',reason:'',evidence:{businessCount:null as number|null,moldLeadDays:null as number|null,bomPushMinutes:null as number|null,fileLookupMinutes:null as number|null,communicationMinutes:null as number|null,notes:''}})
const availableProjects = computed(() => options.value.projects.filter(p => [...form.platformIds, form.newPlatformId].includes(p.parent_product_id)))
async function load() { loading.value=true; error.value='';try{[rows.value, options.value]=await Promise.all([getTrials(),getTrialOptions()])}catch(e){error.value=e instanceof Error?e.message:'查询失败'}finally{loading.value=false} }
async function edit(row?:Trial) { selected.value=row?await getTrial(row.trial_id):null;const t=selected.value;Object.assign(form,{name:t?.name||'',platformIds:t?.platform_ids||[],newPlatformId:t?.new_platform_id||null,projectIds:t?.project_ids||[],reason:'',baseline:{moldLeadDays:null,bomPushMinutes:null,fileLookupMinutes:null,communicationMinutes:null,...t?.baseline}});editOpen.value=true }
async function save() { try { await saveTrial(selected.value?.trial_id||null,{...form,beforeRevision:selected.value?.revision});editOpen.value=false;await load();ElMessage.success('试点范围已保存为准备状态，未启动业务试点') } catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')} }
function prepareStart(row:Trial){selected.value=row;Object.assign(start,{startedOn:'',mexicoAccessVerified:false,supplierVerified:false,erpVerified:false});startOpen.value=true}
async function begin(){if(!selected.value)return;try{await startTrial(selected.value.trial_id,start);startOpen.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'启动失败')}}
async function show(row:Trial){selected.value=await getTrial(row.trial_id);detailOpen.value=true}
async function extend(row:Trial){const reason=await ElMessageBox.prompt('填写双方书面确认的延期依据（最多两周）','调整评审日期',{inputValidator:v=>!!v?.trim()||'依据必填'});const date=await ElMessageBox.prompt('评审日期，格式 YYYY-MM-DD','评审日期');await reviewTrial(row.trial_id,{reviewOn:date.value,reason:reason.value,outcome:'active',evidence:{}});await load()}
function prepareReview(row:Trial){selected.value=row;Object.assign(review,{reviewOn:row.review_on||'',outcome:'passed',reason:'',evidence:{businessCount:null,moldLeadDays:null,bomPushMinutes:null,fileLookupMinutes:null,communicationMinutes:null,notes:''}});reviewOpen.value=true}
async function finishReview(){if(!selected.value)return;try{await reviewTrial(selected.value.trial_id,review);reviewOpen.value=false;await load();ElMessage.success('真实试点评审记录已保存；未知指标未自动补零')}catch(e){ElMessage.error(e instanceof Error?e.message:'评审保存失败')}}
onMounted(load)
</script>
<template>
 <section class="trial-page" v-loading="loading"><header><div><h2>试点范围与评估准备</h2><p>确认七个稳定平台、一款新品和真实新业务；准备完成后才开始四周试点。</p></div><el-button @click="load">刷新</el-button><el-button type="primary" @click="edit()">配置试点</el-button></header>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert title="当前只进行准备，不自动导入历史存量，不生成演示人员或业务。不满足真实跨地域及ERP验证条件时不能启动。" type="info" :closable="false"/>
 <el-table :data="rows" border empty-text="尚未确认真实试点名单。点击配置试点，在现有平台下明确选择新业务。"><el-table-column prop="name" label="试点" min-width="240"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="started_on" label="启动日期" width="150"/><el-table-column prop="review_on" label="评审日期" width="150"/><el-table-column label="操作" min-width="340"><template #default="{row}"><el-button link @click="show(row)">范围与基准</el-button><el-button v-if="row.status==='preparing'" link @click="edit(row)">修改准备</el-button><el-button v-if="row.status==='preparing'" link @click="prepareStart(row)">检查并启动</el-button><el-button v-if="row.status==='active'" link @click="extend(row)">书面延期</el-button><el-button v-if="row.status==='active'" link @click="prepareReview(row)">记录实际评审</el-button><el-button link @click="exportTrial(row.trial_id)">完整导出</el-button></template></el-table-column></el-table>
 <el-drawer v-model="editOpen" title="试点范围与手工模式基准" size="min(1200px,96vw)"><el-form label-position="top"><el-form-item label="试点名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="七个稳定外观平台"><el-select v-model="form.platformIds" multiple filterable style="width:100%"><el-option v-for="p in options.platforms.filter(x=>['released','archived'].includes(x.status))" :key="p.product_id" :value="p.product_id" :label="`${p.product_name} ${p.product_code}`"/></el-select></el-form-item><el-form-item label="一款全新外观平台"><el-select v-model="form.newPlatformId" filterable clearable style="width:100%"><el-option v-for="p in options.platforms" :key="p.product_id" :value="p.product_id" :label="`${p.product_name} ${p.product_code}`"/></el-select></el-form-item><el-form-item label="明确参与试点的新型号项目（不会自动纳入平台全部历史型号）"><el-select v-model="form.projectIds" multiple filterable style="width:100%"><el-option v-for="p in availableProjects" :key="p.product_id" :value="p.product_id" :label="`${p.product_name} ${p.model||''}`"/></el-select></el-form-item><div class="baseline"><el-form-item label="手工模式开模至验收周期（天）"><el-input-number v-model="form.baseline.moldLeadDays" :min="0"/></el-form-item><el-form-item label="BOM推送工时（分钟）"><el-input-number v-model="form.baseline.bomPushMinutes" :min="0"/></el-form-item><el-form-item label="资料查找工时（分钟）"><el-input-number v-model="form.baseline.fileLookupMinutes" :min="0"/></el-form-item><el-form-item label="跨地域沟通工时（分钟）"><el-input-number v-model="form.baseline.communicationMinutes" :min="0"/></el-form-item></div><el-form-item label="配置或修订说明"><el-input v-model="form.reason" type="textarea" :rows="4"/></el-form-item><el-button type="primary" @click="save">保存准备范围</el-button></el-form></el-drawer>
 <el-dialog v-model="startOpen" title="真实验证后启动四周试点" width="min(760px,96vw)"><el-date-picker v-model="start.startedOn" value-format="YYYY-MM-DD" placeholder="实际启动日期"/><div class="checks"><el-checkbox v-model="start.mexicoAccessVerified">墨西哥关键用户已真实访问并操作</el-checkbox><el-checkbox v-model="start.supplierVerified">供应商已完成授权业务提交</el-checkbox><el-checkbox v-model="start.erpVerified">正式BOM及费用ERP接口已真实联调</el-checkbox></div><p>服务器另行校验平台数量、真实账号及对接开关。不能靠勾选绕过未配置的接口。</p><template #footer><el-button @click="startOpen=false">返回准备</el-button><el-button type="primary" @click="begin">确认启动</el-button></template></el-dialog>
 <el-drawer v-model="detailOpen" title="试点配置与基准" size="min(1000px,96vw)"><pre>{{ JSON.stringify(selected,null,2) }}</pre></el-drawer>
 <el-drawer v-model="reviewOpen" title="四周真实业务评审" size="min(1100px,96vw)"><el-alert title="只填写实际采集的观察和证据；未知留空，不用演示数据或推算库存。未完成链路须在说明中如实记录。" :closable="false"/><el-form label-position="top"><el-form-item label="实际评审日期"><el-date-picker v-model="review.reviewOn" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="评审结论"><el-radio-group v-model="review.outcome"><el-radio value="passed">通过</el-radio><el-radio value="failed">不通过</el-radio></el-radio-group></el-form-item><div class="baseline"><el-form-item label="实际业务数量"><el-input-number v-model="review.evidence.businessCount" :min="0" :precision="0"/></el-form-item><el-form-item label="实际开模至验收周期（天）"><el-input-number v-model="review.evidence.moldLeadDays" :min="0"/></el-form-item><el-form-item label="实际BOM推送工时（分钟）"><el-input-number v-model="review.evidence.bomPushMinutes" :min="0"/></el-form-item><el-form-item label="实际资料查找工时（分钟）"><el-input-number v-model="review.evidence.fileLookupMinutes" :min="0"/></el-form-item><el-form-item label="实际跨地域沟通工时（分钟）"><el-input-number v-model="review.evidence.communicationMinutes" :min="0"/></el-form-item></div><el-form-item label="真实记录、证据位置与尚未完成链路"><el-input v-model="review.evidence.notes" type="textarea" :rows="6"/></el-form-item><el-form-item label="双方评审依据"><el-input v-model="review.reason" type="textarea" :rows="4"/></el-form-item><el-button type="primary" @click="finishReview">保存真实评审</el-button></el-form></el-drawer>
 </section>
</template>
<style scoped>.trial-page{display:flex;flex-direction:column;gap:16px;width:100%;min-width:0}header{display:flex;gap:12px;align-items:center;flex-wrap:wrap}header>div{flex:1}h2{margin:0}p{color:#64748b}.baseline{display:grid;grid-template-columns:repeat(2,minmax(240px,1fr));gap:18px}.checks{display:flex;flex-direction:column;gap:16px;margin:24px 0}pre{white-space:pre-wrap;word-break:break-all}@media(max-width:680px){.baseline{grid-template-columns:1fr}}</style>
